{
  "name": "@alessiods/noclank",
  "version": "1.0.3",
  "description": "Kills AI-generated clankerspeech slop. Forces plain, direct, human-sounding prose.",
  "keywords": [
    "opencode-plugin",
    "opencode",
    "noclank",
    "pi-package",
    "pi",
    "skills",
    "clankerspeech",
    "anti-ai-slop"
  ],
  "license": "MIT",
  "author": {
    "name": "no-clank",
    "url": "https://github.com/alessio-ds/no-clank"
  },
  "homepage": "https://github.com/alessio-ds/no-clank",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/alessio-ds/no-clank.git"
  },
  "bugs": {
    "url": "https://github.com/alessio-ds/no-clank/issues"
  },
  "main": "./.opencode/plugins/noclank.mjs",
  "exports": {
    ".": "./.opencode/plugins/noclank.mjs",
    "./plugin": "./.opencode/plugins/noclank.mjs"
  },
  "files": [
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    "pi-extension/",
    "assets/",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test tests/*.test.js"
  },
  "pi": {
    "extensions": [
      "./pi-extension/index.js"
    ],
    "skills": [
      "./skills"
    ]
  },
  "publishConfig": {
    "access": "public"
  }
}
